"""
Generation of test doubles for testing of consumer methods.
"""

from .contracts import data_types_by_contract


def provider_mock(contract, **contract_data):
    """Generate a mock provider for the given contract.

    **Use this method to generate a mock contract-supporting object that can be
    passed to consumer methods during tests.**

    :param contract: The contract to generate a mock provider for.
    :param contract_data: The data to be used for the provider.
    :raises TypeError: If not all necessary keys are provided in the ``contract_data``.
    :return: A mock provider.
    """
    data_type = data_types_by_contract[contract]
    missing_keys = set(data_type.__required_keys__).difference(contract_data.keys())
    if missing_keys:
        keys_msg = ", ".join(missing_keys)
        raise TypeError(
            f"Mock creation failed. "
            f"Given data is missing keys required by the contract: {keys_msg}"
        )
    provider_method_name = f"__taf_contract_{contract.__name__.lower()}__"
    mock_class = type(
        f"Mock{contract.__name__}Provider",
        (),
        {provider_method_name: lambda _: contract_data},
    )
    return mock_class()
